import React, { useEffect, useState, useRef } from 'react';
import { fetchReviews } from '../api/reviewApi';
import ReviewCard from '../components/ReviewCard';
import axios from '../api/axiosConfig';

function Magazine() {
  const [summary, setSummary] = useState(null);
  const [loading, setLoading] = useState(false);
  const [trails, setTrails] = useState([]);
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });
  const containerRef = useRef(null);
  const trailIdRef = useRef(0);

  // 마우스 추적 + 브러쉬 트레일 효과
  useEffect(() => {
    const handleMouseMove = (e) => {
      if (containerRef.current) {
        const rect = containerRef.current.getBoundingClientRect();
        setMousePos({
          x: ((e.clientX - rect.left) / rect.width) * 100,
          y: ((e.clientY - rect.top) / rect.height) * 100
        });
        
        // 파스텔 노란색 브러쉬 트레일
        const newTrail = {
          id: trailIdRef.current++,
          x: e.clientX,
          y: e.clientY,
          size: Math.random() * 24 + 12,
          color: ['#fff9c4', '#fff59d', '#ffe082', '#ffecb3', '#fff176', '#ffee58', '#ffefd5', '#fffacd'][Math.floor(Math.random() * 8)],
          opacity: 0.85
        };
        setTrails(prev => [...prev.slice(-20), newTrail]);
      }
    };
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  // 트레일 페이드아웃
  useEffect(() => {
    if (trails.length === 0) return;
    const timer = setInterval(() => {
      setTrails(prev => prev.filter(t => Date.now() - t.id < 680).map(t => ({
        ...t,
        opacity: Math.max(0, t.opacity - 0.055),
        size: t.size * 0.94
      })));
    }, 45);
    return () => clearInterval(timer);
  }, [trails.length]);

  useEffect(() => {
    const load = async () => {
      try {
        setLoading(true);
        // 예시: 최신 리뷰 몇 개를 AI 요약 API로 보냄
        const reviewsRes = await fetchReviews({ page: 1, limit: 8 });
        const texts = reviewsRes.data.map(r => r.text);
        const resp = await axios.post('/ai/summarize', { texts });
        setSummary(resp.data.summary);
      } catch (err) {
        console.error('magazine load failed', err);
      } finally {
        setLoading(false);
      }
    };
    load();
  }, []);

  return (
    <div 
      ref={containerRef}
      style={{ 
        padding: 20, 
        minHeight: '100vh',
        background: `
          radial-gradient(circle at ${mousePos.x}% ${mousePos.y}%, rgba(255,77,136,0.08) 0%, transparent 50%),
          linear-gradient(180deg, #fff 0%, #fff5f7 50%, #faf5ff 100%)
        `,
        position: 'relative'
      }}
    >
      {/* 🎨 파스텔 노란색 브러쉬 트레일 */}
      {trails.map((trail) => (
        <div
          key={trail.id}
          style={{
            position: 'fixed',
            left: trail.x,
            top: trail.y,
            width: trail.size,
            height: trail.size,
            borderRadius: '50%',
            background: `radial-gradient(circle, ${trail.color} 0%, ${trail.color}88 40%, transparent 70%)`,
            opacity: trail.opacity,
            pointerEvents: 'none',
            zIndex: 9999,
            filter: 'blur(1px)',
            boxShadow: `0 0 ${trail.size}px ${trail.color}`,
            transform: 'translate(-50%, -50%)'
          }}
        />
      ))}

      <h1>📰 AI 리뷰 매거진</h1>
      <p style={{ color: '#666' }}>AI가 여러 리뷰를 뽑아 트렌드와 핵심을 정리해드립니다.</p>

      {loading && <p>요약 생성 중...</p>}

      {summary && (
        <div style={{ marginTop: 16, padding: 16, background: '#fff', borderRadius: 8, boxShadow: '0 8px 20px rgba(0,0,0,0.04)' }}>
          <div dangerouslySetInnerHTML={{ __html: summary.replace(/\n/g, '<br/>') }} />
        </div>
      )}
    </div>
  );
}

export default Magazine;
